	s.loginFailures.clear(loginFailureKey(user.Username, clientIP(r)))
	http.SetCookie(w, &http.Cookie{
		Name: sessionCookieName, Value: session.Token, Path: "/", HttpOnly: true, SameSite: http.SameSiteLaxMode,
